#include <iostream>
struct X {
    int i;
    int j;
    int k = 42;  // Default member initializer
};

int main() {
    X a[] = {1, 2, 3, 4, 5, 6};  // Initializes two X objects: first {i=1, j=2, k=3}, second {i=4, j=5, k=6}
    X b[2] = {{1, 2, 3}, {4, 5, 6}};  // Explicitly: first {i=1, j=2, k=3}, second {i=4, j=5, k=6}
    // a and b have the same values due to aggregate initialization rules
    std::cout << a[0].i << ' ' << a[0].j << ' ' << a[0].k << std::endl;  // Outputs: 1 2 3
    return 0;
}
